let inscrit = false;
const statut = document.querySelector("#statut");
document.querySelector("#basculer").addEventListener("click", function () {
  inscrit = !inscrit;
  statut.textContent = inscrit ? "Inscrit" : "Non inscrit";
});
document.querySelector("#annuler").addEventListener("click", function () {
  inscrit = false;
  statut.textContent = "Non inscrit";
});

